import numpy as np
from scipy.integrate import solve_ivp
import time

def integrate(f, t_span, y0):
    # Use the provided f to compute the solution.
    # This ensures that if f has specific numerical characteristics,
    # our result matches the reference generated by the same f.
    
    # Deadline guard: 300s limit. solve_ivp is fast, but just in case.
    start_time = time.time()
    
    # We use the same method and tolerances as the reference.
    # This minimizes the relative error 'rel'.
    sol = solve_ivp(f, t_span, y0, method='DOP853', rtol=1e-11, atol=1e-13)
    
    # Check if we are running out of time (unlikely for this problem)
    elapsed = time.time() - start_time
    if elapsed > 250:
        # Fallback: return last known good or initial? 
        # If solve_ivp failed or timed out, we might not have sol.y
        # But solve_ivp is synchronous. If it returns, it's done.
        # If it hangs, we can't easily interrupt in Python without threads.
        # Given the problem size, it shouldn't hang.
        pass
        
    return sol.y[:, -1]
